@charset "UTF-8";
@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap");
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
}

body {
  font-family: "DM Sans", sans-serif;
  background: transparent;
  color: #2F323B;
}

button,
select {
  font-family: inherit;
}

.summary-shell {
  --ink: #2F323B;
  --blue: #2972A9;
  --cyan: #2E9BCB;
  --light-blue: #A7CDDE;
  --paper: #FFFFFF;
  --surface: #F7FAFC;
  --surface-blue: rgba(167, 205, 222, 0.13);
  --line: rgba(167, 205, 222, 0.55);
  --line-soft: rgba(167, 205, 222, 0.28);
  --muted: #727780;
  --green: #1EAF73;
  --red: #E6505C;
  --orange: #E79A2E;
  width: 100%;
  min-height: 100%;
  display: grid;
  grid-template-columns: 190px minmax(0, 1fr);
  gap: 14px;
  padding: 8px;
  background: linear-gradient(180deg, #F8FBFD 0%, #FFFFFF 100%);
}

/* =========================================================
   SIDEBAR
   ========================================================= */
.summary-sidebar {
  min-height: 680px;
  padding: 16px 10px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(247, 250, 252, 0.98), rgba(255, 255, 255, 0.98));
  box-shadow: 0 10px 24px rgba(47, 50, 59, 0.06);
}

.sidebar-heading {
  padding: 5px 10px 16px;
  display: flex;
  flex-direction: column;
}

.sidebar-heading span {
  color: var(--cyan);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.15em;
}

.sidebar-heading strong {
  margin-top: 4px;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 18px;
}

.summary-nav {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.summary-nav-item {
  width: 100%;
  min-height: 54px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 8px 10px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  text-align: left;
  transition: color 0.2s, background 0.2s, transform 0.2s;
}

.summary-nav-item:hover {
  color: var(--blue);
  background: rgba(167, 205, 222, 0.14);
}

.summary-nav-item.active {
  color: var(--blue);
  background: linear-gradient(90deg, rgba(46, 155, 203, 0.15), rgba(167, 205, 222, 0.1));
}

.summary-nav-item.active::before {
  content: "";
  width: 3px;
  height: 30px;
  margin-left: -10px;
  border-radius: 0 4px 4px 0;
  background: linear-gradient(180deg, var(--blue), var(--cyan));
}

.summary-nav-icon {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 9px;
  background: rgba(41, 114, 169, 0.07);
  font-size: 14px;
  font-weight: 700;
}

.summary-nav-item.active .summary-nav-icon {
  background: rgba(46, 155, 203, 0.14);
}

.summary-nav-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.summary-nav-copy strong {
  color: inherit;
  font-size: 11px;
  font-weight: 700;
}

.summary-nav-copy small {
  margin-top: 2px;
  color: #969BA2;
  font-size: 8px;
}

/* =========================================================
   MAIN
   ========================================================= */
.summary-main {
  min-width: 0;
  padding: 4px 2px 14px;
}

.summary-header {
  min-height: 78px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 14px;
}

.summary-heading {
  min-width: 0;
}

.summary-kicker {
  color: var(--cyan);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.15em;
}

.summary-heading h1 {
  margin-top: 3px;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 27px;
  line-height: 1.1;
}

.summary-heading p {
  margin-top: 5px;
  color: var(--muted);
  font-size: 10px;
}

.summary-header-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.query-context {
  min-width: 170px;
  height: 45px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #FFFFFF;
}

.query-context-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #47D7A0;
  flex-shrink: 0;
}

.query-context div {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.query-context small {
  color: #969BA2;
  font-size: 7px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.query-context strong {
  max-width: 145px;
  margin-top: 2px;
  overflow: hidden;
  color: var(--ink);
  font-size: 9px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.period-selector {
  height: 45px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 9px 0 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #FFFFFF;
}

.period-selector span {
  color: #969BA2;
  font-size: 8px;
}

.period-selector select {
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font-size: 9px;
  font-weight: 600;
  cursor: pointer;
}

/* =========================================================
   VIEWS
   ========================================================= */
.summary-view {
  display: none;
}

.summary-view.active {
  display: block;
}

/* =========================================================
   METRICS
   ========================================================= */
.metric-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.metric-card {
  min-height: 112px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 8px 22px rgba(47, 50, 59, 0.045);
}

.metric-top {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 600;
}

.metric-icon {
  width: 31px;
  height: 31px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(46, 155, 203, 0.09);
  color: var(--blue);
  font-size: 14px;
  font-weight: 700;
}

.metric-icon.warning {
  color: var(--orange);
  background: rgba(231, 154, 46, 0.11);
}

.metric-value {
  display: block;
  margin-top: 12px;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 26px;
  line-height: 1;
}

.metric-value-small {
  font-size: 17px;
}

.metric-foot {
  display: block;
  margin-top: 7px;
  color: #989DA4;
  font-size: 8px;
}

/* =========================================================
   PANELS
   ========================================================= */
.content-grid {
  display: grid;
  gap: 12px;
  margin-top: 12px;
}

.primary-grid {
  grid-template-columns: minmax(0, 1.65fr) minmax(280px, 0.95fr);
}

.secondary-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.panel-card {
  min-width: 0;
  min-height: 235px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 8px 22px rgba(47, 50, 59, 0.045);
}

.panel-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.panel-heading h2 {
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 15px;
}

.panel-heading p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 8px;
}

.panel-badge {
  padding: 5px 9px;
  border-radius: 8px;
  background: rgba(167, 205, 222, 0.14);
  color: var(--blue);
  font-size: 8px;
  font-weight: 600;
}

/* =========================================================
   PLACEHOLDERS
   ========================================================= */
.empty-chart {
  height: 170px;
  margin-top: 14px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  overflow: hidden;
  background: repeating-linear-gradient(to bottom, transparent 0, transparent 32px, rgba(167, 205, 222, 0.22) 33px);
}

.empty-chart::before {
  content: "";
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 20px;
  height: 58px;
  border-bottom: 2px solid rgba(46, 155, 203, 0.28);
  transform: skewY(-3deg);
  opacity: 0.7;
}

.empty-chart span {
  position: relative;
  z-index: 2;
  padding: 8px 11px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.88);
  color: #969BA2;
  font-size: 8px;
}

.empty-donut {
  min-height: 170px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  margin-top: 8px;
}

.donut-placeholder {
  width: 120px;
  height: 120px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: conic-gradient(#35BF83 0deg 120deg, #B8C1CA 120deg 245deg, #EF626C 245deg 360deg);
  position: relative;
}

.donut-placeholder.muted {
  background: conic-gradient(#2972A9 0deg 170deg, #2E9BCB 170deg 250deg, #A7CDDE 250deg 315deg, #DCE5EA 315deg 360deg);
}

.donut-placeholder::after {
  content: "";
  position: absolute;
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: #FFFFFF;
}

.donut-placeholder div {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 18px;
}

.donut-placeholder small {
  margin-top: 2px;
  color: #969BA2;
  font-family: "DM Sans", sans-serif;
  font-size: 7px;
}

.legend-list {
  min-width: 120px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.legend-list div {
  display: grid;
  grid-template-columns: 9px 1fr auto;
  gap: 6px;
  align-items: center;
  color: var(--muted);
  font-size: 8px;
}

.legend-list strong {
  color: var(--ink);
}

.legend-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.legend-dot.positive {
  background: #35BF83;
}

.legend-dot.neutral {
  background: #B8C1CA;
}

.legend-dot.negative {
  background: #EF626C;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.empty-state.compact {
  min-height: 155px;
}

.empty-state strong {
  color: var(--ink);
  font-size: 10px;
}

.empty-state span {
  max-width: 260px;
  margin-top: 5px;
  color: #969BA2;
  font-size: 8px;
}

/* conversación */
.topic-placeholder-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
  margin-top: 20px;
}

.topic-placeholder-grid span {
  min-height: 65px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 18px;
  background: rgba(167, 205, 222, 0.14);
  color: #9BA0A7;
  font-size: 8px;
}

/* fuentes */
.bar-placeholder {
  height: 165px;
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  gap: 12px;
  padding: 20px 24px 0;
  margin-top: 5px;
  border-bottom: 1px solid rgba(167, 205, 222, 0.35);
}

.bar-placeholder span {
  width: 11%;
  min-height: 18px;
  border-radius: 7px 7px 0 0;
  background: linear-gradient(180deg, rgba(46, 155, 203, 0.75), rgba(41, 114, 169, 0.9));
  opacity: 0.6;
}

/* actores */
.actor-placeholder-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 9px;
  margin-top: 18px;
}

.actor-placeholder {
  min-height: 130px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10px;
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  background: #FFFFFF;
}

.actor-placeholder > span {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: linear-gradient(145deg, #E7F3F9, #D5E7EF);
}

.actor-placeholder strong {
  margin-top: 8px;
  color: var(--ink);
  font-size: 9px;
}

.actor-placeholder small {
  margin-top: 2px;
  color: #969BA2;
  font-size: 7px;
}

.network-placeholder {
  min-height: 170px;
  margin-top: 8px;
  position: relative;
  border-radius: 12px;
  background: radial-gradient(circle at center, rgba(46, 155, 203, 0.09), transparent 47%);
}

.network-node {
  position: absolute;
  min-width: 54px;
  padding: 6px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: #FFFFFF;
  color: var(--blue);
  font-size: 7px;
  text-align: center;
}

.node-main {
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: #FFFFFF;
  background: linear-gradient(135deg, var(--blue), var(--cyan));
}

.node-a {
  left: 9%;
  top: 21%;
}

.node-b {
  right: 10%;
  top: 18%;
}

.node-c {
  right: 17%;
  bottom: 15%;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */
@media (max-width: 1100px) {
  .summary-shell {
    grid-template-columns: 76px minmax(0, 1fr);
  }
  .sidebar-heading {
    display: none;
  }
  .summary-nav-copy {
    display: none;
  }
  .summary-nav-item {
    justify-content: center;
  }
  .summary-nav-item.active::before {
    position: absolute;
    left: 0;
    margin-left: 0;
  }
  .summary-nav-item {
    position: relative;
  }
  .metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .actor-placeholder-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 780px) {
  .summary-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .summary-header-controls {
    width: 100%;
    flex-wrap: wrap;
  }
  .query-context {
    flex: 1;
  }
  .metric-grid,
  .primary-grid,
  .secondary-grid {
    grid-template-columns: 1fr;
  }
}

