appsmith.onReady(function () {
  var validViews = ['overview', 'conversation', 'sources', 'actors'];
  var validPeriods = ['24h', '7d', '30d', '90d'];
  var viewMeta = {
    overview: {
      title: 'Panorama general',
      subtitle: 'Comportamiento de las redes sociales incorporadas al histórico.'
    },
    conversation: {
      title: 'Conversación',
      subtitle: 'Actividad, contenido y temas presentes en las publicaciones ingeridas.'
    },
    sources: {
      title: 'Fuentes',
      subtitle: 'Distribución de actividad entre plataformas y cuentas sociales.'
    },
    actors: {
      title: 'Actores',
      subtitle: 'Cuentas mencionadas y relaciones identificadas dentro de las publicaciones.'
    }
  };
  var palette = ['#2972A9', '#2E9BCB', '#31B98A', '#E6A23C', '#7968D6', '#E76F6F', '#3C8DAD', '#D67EBC'];
  var currentView = normalizeView(appsmith.model && appsmith.model.activeView || 'overview');
  var currentPeriod = normalizePeriod(appsmith.model && appsmith.model.period || '30d');
  var lastRefreshKey = '';

  /* =========================================================
     MODELO
     ========================================================= */

  function getModel(modelOverride) {
    return modelOverride || appsmith.model || {};
  }
  function normalizeView(value) {
    var valueNormalized = String(value || '').trim().toLowerCase();
    if (validViews.indexOf(valueNormalized) !== -1) {
      return valueNormalized;
    }
    return 'overview';
  }
  function normalizePeriod(value) {
    var valueNormalized = String(value || '').trim().toLowerCase();
    if (validPeriods.indexOf(valueNormalized) !== -1) {
      return valueNormalized;
    }
    return '30d';
  }
  function getPeriodLabel(period) {
    if (period === '24h') {
      return '24 h';
    }
    if (period === '7d') {
      return '7 días';
    }
    if (period === '90d') {
      return '90 días';
    }
    return '30 días';
  }
  function parseArray(value) {
    if (Array.isArray(value)) {
      return value;
    }
    if (typeof value !== 'string' || value.trim() === '') {
      return [];
    }
    var text = value.trim();
    try {
      var decoded = decodeURIComponent(text);
      var parsed = JSON.parse(decoded);
      return Array.isArray(parsed) ? parsed : [];
    } catch (decodedError) {
      try {
        var direct = JSON.parse(text);
        return Array.isArray(direct) ? direct : [];
      } catch (directError) {
        return [];
      }
    }
  }
  function getCoreRow(modelOverride) {
    var model = getModel(modelOverride);
    var rows = parseArray(model.summarySocialCore);
    if (rows.length === 0) {
      return null;
    }
    var row = rows[0] || null;
    if (!row) {
      return null;
    }
    if (row.period && normalizePeriod(row.period) !== currentPeriod) {
      return null;
    }
    return row;
  }
  function getHistoryRow(modelOverride) {
    var model = getModel(modelOverride);
    var rows = parseArray(model.summaryMetricHistory);
    if (rows.length === 0) {
      return null;
    }
    var row = rows[0] || null;
    if (!row) {
      return null;
    }
    if (row.period && normalizePeriod(row.period) !== currentPeriod) {
      return null;
    }
    return row;
  }
  function getArrayField(row, field) {
    if (!row || !Array.isArray(row[field])) {
      return [];
    }
    return row[field];
  }

  /* =========================================================
     UTILIDADES
     ========================================================= */

  function escapeHtml(value) {
    return String(value === null || value === undefined ? '' : value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
  }
  function cleanText(value) {
    return String(value || '').replace(/\s+/g, ' ').trim();
  }
  function truncate(value, limit) {
    var text = cleanText(value);
    if (text.length <= limit) {
      return text;
    }
    return text.slice(0, limit - 1).trim() + '…';
  }
  function formatNumber(value) {
    var number = Number(value);
    if (!Number.isFinite(number)) {
      number = 0;
    }
    return new Intl.NumberFormat('es-MX').format(number);
  }
  function formatDecimal(value) {
    var number = Number(value);
    if (!Number.isFinite(number)) {
      number = 0;
    }
    return new Intl.NumberFormat('es-MX', {
      maximumFractionDigits: 2
    }).format(number);
  }
  function formatDateTime(value) {
    if (!value) {
      return 'Sin actividad';
    }
    var date = new Date(value);
    if (Number.isNaN(date.getTime())) {
      return 'Sin actividad';
    }
    return new Intl.DateTimeFormat('es-MX', {
      timeZone: 'America/Mexico_City',
      day: '2-digit',
      month: 'short',
      hour: '2-digit',
      minute: '2-digit'
    }).format(date);
  }
  function formatShortDate(value) {
    if (!value) {
      return '';
    }
    var text = String(value);
    var date = new Date(text.indexOf('T') !== -1 ? text : text + 'T12:00:00');
    if (Number.isNaN(date.getTime())) {
      return text;
    }
    return new Intl.DateTimeFormat('es-MX', {
      day: '2-digit',
      month: 'short'
    }).format(date);
  }
  function platformLabel(platform) {
    var value = String(platform || '').trim().toLowerCase();
    if (value === 'facebook') {
      return 'Facebook';
    }
    if (value === 'instagram') {
      return 'Instagram';
    }
    if (value === 'youtube') {
      return 'YouTube';
    }
    if (value === 'tiktok') {
      return 'TikTok';
    }
    if (value === 'x' || value === 'twitter') {
      return 'X';
    }
    return value || 'Otra';
  }
  function postTypeLabel(type) {
    var value = String(type || '').trim().toLowerCase();
    if (value === 'video') {
      return 'Video';
    }
    if (value === 'post') {
      return 'Publicación';
    }
    if (value === 'carrusel') {
      return 'Carrusel';
    }
    if (value === 'imagen') {
      return 'Imagen';
    }
    return value || 'Sin tipo';
  }
  function getColor(index) {
    return palette[index % palette.length];
  }
  function safeUrl(value) {
    var url = String(value || '').trim();
    if (/^https?:\/\//i.test(url)) {
      return url;
    }
    return '';
  }
  function normalizeHandle(value) {
    var handle = String(value || '').trim().toLowerCase();
    handle = handle.replace(/[.,;:!?]+$/g, '');
    if (handle && handle.charAt(0) !== '@') {
      handle = '@' + handle;
    }
    return handle;
  }

  /* =========================================================
     ACTORES
     ========================================================= */

  function normalizeActors(rows) {
    var map = {};
    (Array.isArray(rows) ? rows : []).forEach(function (row) {
      var handle = normalizeHandle(row.handle);
      if (!handle) {
        return;
      }
      if (!map[handle]) {
        map[handle] = {
          handle: handle,
          posts: 0,
          source_accounts: 0,
          first_seen_period: row.first_seen_period || null,
          first_seen_history: row.first_seen_history || null,
          last_activity: row.last_activity || null,
          is_new: row.is_new === true
        };
      }
      map[handle].posts += Number(row.posts || 0);
      map[handle].source_accounts = Math.max(map[handle].source_accounts, Number(row.source_accounts || 0));
      if (row.last_activity && (!map[handle].last_activity || new Date(row.last_activity) > new Date(map[handle].last_activity))) {
        map[handle].last_activity = row.last_activity;
      }
      if (row.first_seen_history && (!map[handle].first_seen_history || new Date(row.first_seen_history) < new Date(map[handle].first_seen_history))) {
