  function normalizeEdges(rows) {
    var map = {};
    (Array.isArray(rows) ? rows : []).forEach(function (row) {
      var source = String(row.source_handle || '').trim();
      var target = normalizeHandle(row.mentioned_handle);
      if (!source || !target) {
        return;
      }
      var key = source + '|' + String(row.platform || '') + '|' + target;
      if (!map[key]) {
        map[key] = {
