  /* =========================================================
     GRÁFICO
     ========================================================= */

  function buildTimelineChart(timeline, field, color, note) {
    if (!Array.isArray(timeline) || timeline.length === 0) {
      return buildZeroState('Sin actividad', 'No existen datos para el periodo.');
    }
    var rows = timeline.map(function (row) {
      return {
        bucket: row.bucket,
        value: Number(row[field] || 0)
      };
    });
    var maxValue = Math.max(1, Math.max.apply(null, rows.map(function (row) {
      return row.value;
    })));
    var width = 1000;
    var height = 205;
    var padX = 22;
    var padTop = 16;
    var padBottom = 26;
    var usableWidth = width - padX * 2;
    var usableHeight = height - padTop - padBottom;
    var points = rows.map(function (row, index) {
      var denominator = Math.max(rows.length - 1, 1);
      return {
        x: padX + index / denominator * usableWidth,
        y: padTop + usableHeight - row.value / maxValue * usableHeight,
        value: row.value,
        bucket: row.bucket
      };
    });
    var polyline = points.map(function (point) {
      return point.x.toFixed(2) + ',' + point.y.toFixed(2);
    }).join(' ');
    var grid = [0, 0.25, 0.5, 0.75, 1].map(function (ratio) {
      var y = padTop + usableHeight * ratio;
      return '<line' + ' class="summary-chart-grid"' + ' x1="' + padX + '"' + ' y1="' + y + '"' + ' x2="' + (width - padX) + '"' + ' y2="' + y + '"' + '></line>';
    }).join('');
    var dots = points.filter(function (point) {
      return point.value > 0;
    }).map(function (point, index) {
      return '<circle' + ' class="summary-chart-point"' + ' cx="' + point.x + '"' + ' cy="' + point.y + '"' + ' r="4.5"' + ' fill="' + getColor(index + 1) + '"' + '>' + '<title>' + escapeHtml(point.bucket + ': ' + formatNumber(point.value)) + '</title>' + '</circle>';
    }).join('');
    var first = rows[0];
    var middle = rows[Math.floor((rows.length - 1) / 2)];
    var last = rows[rows.length - 1];
    return '<div class="summary-live-chart">' + '<svg' + ' viewBox="0 0 1000 205"' + ' preserveAspectRatio="none"' + '>' + grid + '<polyline' + ' class="summary-chart-line"' + ' stroke="' + color + '"' + ' points="' + polyline + '"' + '></polyline>' + dots + '</svg>' + '<div class="summary-chart-labels">' + '<span>' + escapeHtml(formatShortDate(first.bucket)) + '</span>' + '<span>' + escapeHtml(formatShortDate(middle.bucket)) + '</span>' + '<span>' + escapeHtml(formatShortDate(last.bucket)) + '</span>' + '</div>' + (note ? '<div class="summary-history-note">' + '<span></span>' + '<strong>' + escapeHtml(note) + '</strong>' + '</div>' : '') + '</div>';
  }

  /* =========================================================
     DONUT
     ========================================================= */

  function buildDonut(items, centerValue, centerLabel) {
    var rows = (Array.isArray(items) ? items : []).filter(function (item) {
      return Number(item.value || 0) > 0;
    });
    var total = rows.reduce(function (sum, item) {
      return sum + Number(item.value || 0);
    }, 0);
    if (total <= 0) {
      return buildZeroState('0 registros', 'No hay información para construir la distribución.');
    }
    var cursor = 0;
    var segments = rows.map(function (item, index) {
      var start = cursor;
      var end = cursor + Number(item.value) / total * 100;
      cursor = end;
      return getColor(index) + ' ' + start.toFixed(2) + '% ' + end.toFixed(2) + '%';
    }).join(',');
    var legend = rows.map(function (item, index) {
      var percentage = Number(item.value) / total * 100;
      return '<div class="summary-live-legend-row">' + '<span' + ' class="summary-live-legend-dot"' + ' style="background:' + getColor(index) + '"' + '></span>' + '<span class="summary-live-legend-name">' + escapeHtml(item.label) + '</span>' + '<strong>' + formatNumber(item.value) + ' · ' + formatDecimal(percentage) + '%' + '</strong>' + '</div>';
    }).join('');
    return '<div class="summary-live-donut-layout">' + '<div' + ' class="summary-live-donut"' + ' style="background:conic-gradient(' + segments + ')"' + '>' + '<div class="summary-live-donut-center">' + '<strong>' + escapeHtml(centerValue) + '</strong>' + '<small>' + escapeHtml(centerLabel) + '</small>' + '</div>' + '</div>' + '<div class="summary-live-legend">' + legend + '</div>' + '</div>';
  }

  /* =========================================================
     HASHTAGS
     ========================================================= */

  function buildHashtags(rows, limit) {
    rows = (Array.isArray(rows) ? rows : []).slice(0, limit);
    if (rows.length === 0) {
      return buildZeroState('0 hashtags', 'No se detectaron hashtags.');
    }
    var max = Math.max.apply(null, rows.map(function (row) {
      return Number(row.posts || 0);
    }));
    return '<div class="summary-hashtags">' + rows.map(function (row, index) {
      var posts = Number(row.posts || 0);
      var percent = max > 0 ? posts / max * 100 : 0;
      return '<div class="summary-hashtag-row">' + '<span class="summary-hashtag-name">' + escapeHtml(row.hashtag) + '</span>' + '<span class="summary-hashtag-value">' + formatNumber(posts) + ' posts' + '</span>' + '<div class="summary-progress">' + '<span' + ' style="' + 'width:' + Math.max(3, percent) + '%;' + 'background:' + getColor(index) + '"' + '></span>' + '</div>' + '</div>';
    }).join('') + '</div>';
  }

  /* =========================================================
