      return buildZeroState('0 publicaciones', 'No existen publicaciones en este periodo.');
    }
    return '<div class="summary-post-list">' + rows.map(function (row, index) {
      var url = safeUrl(row.post_url);
      var text = truncate(row.content_text || 'Publicación sin texto', 145);
      var content = url ? '<a' + ' href="' + escapeHtml(url) + '"' + ' target="_blank"' + ' rel="noopener noreferrer"' + ' style="text-decoration:none;color:inherit"' + '>' + escapeHtml(text) + '</a>' : escapeHtml(text);
      return '<article class="summary-post-item">' + '<span' + ' class="summary-post-accent"' + ' style="background:' + getColor(index) + '"' + '></span>' + '<div class="summary-post-copy">' + '<strong>' + content + '</strong>' + '<small>' + escapeHtml(platformLabel(row.platform) + ' · @' + String(row.handle || '').replace(/^@/, '') + ' · ' + formatDateTime(row.event_at)) + '</small>' + '<div class="summary-post-stats">' + '<span>' + '♥ ' + formatNumber(row.likes) + '</span>' + '<span>' + '◯ ' + formatNumber(row.comments) + '</span>' + '<span>' + '↗ ' + formatNumber(row.interactions) + '</span>' + (Number(row.views || 0) > 0 ? '<span>' + '▶ ' + formatNumber(row.views) + '</span>' : '') + '</div>' + '</div>' + '</article>';
    }).join('') + '</div>';
  }

  /* =========================================================
     PLATAFORMAS
     ========================================================= */

  function buildPlatformBars(rows) {
    if (!Array.isArray(rows) || rows.length === 0) {
      return buildZeroState('0 plataformas', 'No existen plataformas con actividad.');
    }
    var max = Math.max.apply(null, rows.map(function (row) {
      return Number(row.posts || 0);
    }));
    return rows.map(function (row, index) {
      var posts = Number(row.posts || 0);
      var height = max > 0 ? posts / max * 100 : 0;
      return '<div class="summary-platform-bar-item">' + '<span class="summary-platform-bar-value">' + formatNumber(posts) + '</span>' + '<div class="summary-platform-bar-track">' + '<span' + ' class="summary-platform-bar"' + ' style="' + 'height:' + Math.max(6, height) + '%;' + 'background:linear-gradient(' + '180deg,' + getColor(index) + ',' + getColor(index + 1) + ')' + '"' + '></span>' + '</div>' + '<span class="summary-platform-bar-label">' + escapeHtml(platformLabel(row.platform)) + '</span>' + '</div>';
    }).join('');
  }
  function buildPlatformTable(rows) {
    if (!Array.isArray(rows) || rows.length === 0) {
      return buildZeroState('0 plataformas', 'No existen plataformas con actividad.');
    }
    return '<div class="summary-platform-list">' + rows.map(function (row) {
      return '<div class="summary-table-row">' + '<div class="summary-table-main">' + '<strong>' + escapeHtml(platformLabel(row.platform)) + '</strong>' + '<small>' + formatNumber(row.posts) + ' posts · ' + formatNumber(row.comments) + ' comentarios' + '</small>' + '</div>' + '<span class="summary-table-number">' + formatNumber(row.interactions) + ' inter.' + '</span>' + '<span class="summary-table-date">' + escapeHtml(formatDateTime(row.last_activity)) + '</span>' + '</div>';
    }).join('') + '</div>';
  }
  function buildAccountTable(rows) {
    if (!Array.isArray(rows) || rows.length === 0) {
      return buildZeroState('0 cuentas', 'No existen cuentas con publicaciones.');
    }
    return '<div class="summary-account-list">' + rows.map(function (row) {
      return '<div class="summary-table-row">' + '<div class="summary-table-main">' + '<strong>' + escapeHtml('@' + String(row.handle || '').replace(/^@/, '')) + '</strong>' + '<small>' + escapeHtml(platformLabel(row.platform)) + ' · ' + formatNumber(row.posts) + ' posts' + '</small>' + '</div>' + '<span class="summary-table-number">' + formatNumber(row.interactions) + ' inter.' + '</span>' + '<span class="summary-table-date">' + escapeHtml(formatDateTime(row.last_activity)) + '</span>' + '</div>';
    }).join('') + '</div>';
  }

  /* =========================================================
     ACTORES VISUALES
     ========================================================= */

  function buildActorCards(actors) {
    actors = actors.slice(0, 4);
    if (actors.length === 0) {
      return buildZeroState('0 actores', 'No se detectaron cuentas mencionadas.');
    }
    return actors.map(function (actor, index) {
      return '<article class="summary-actor-card">' + '<span' + ' class="summary-actor-avatar"' + ' style="background:linear-gradient(' + '135deg,' + getColor(index) + ',' + getColor(index + 1) + ')"' + '>' + '@' + '</span>' + '<strong title="' + escapeHtml(actor.handle) + '">' + escapeHtml(actor.handle) + '</strong>' + '<small>' + formatNumber(actor.posts) + ' publicaciones' + '</small>' + '</article>';
    }).join('');
  }
  function buildActorRanking(actors) {
    if (actors.length === 0) {
      return buildZeroState('0 actores', 'No existen cuentas mencionadas.');
    }
    var max = Math.max.apply(null, actors.map(function (actor) {
      return actor.posts;
    }));
    return '<div class="summary-ranking">' + actors.slice(0, 10).map(function (actor, index) {
      var percentage = max > 0 ? actor.posts / max * 100 : 0;
      return '<div class="summary-ranking-row">' + '<span class="summary-ranking-name">' + escapeHtml(actor.handle) + '</span>' + '<span class="summary-ranking-value">' + formatNumber(actor.posts) + ' posts' + '</span>' + '<div class="summary-progress">' + '<span' + ' style="' + 'width:' + Math.max(3, percentage) + '%;' + 'background:' + getColor(index) + '"' + '></span>' + '</div>' + '</div>';
    }).join('') + '</div>';
  }
  function buildActorActivity(actors) {
    if (actors.length === 0) {
      return buildZeroState('0 actividades', 'No existe actividad de actores.');
    }
    var sorted = actors.slice().sort(function (a, b) {
      return new Date(b.last_activity || 0) - new Date(a.last_activity || 0);
    });
    return '<div class="summary-actor-list">' + sorted.slice(0, 8).map(function (actor) {
      return '<div class="summary-table-row">' + '<div class="summary-table-main">' + '<strong>' + escapeHtml(actor.handle) + '</strong>' + '<small>' + (actor.is_new ? 'Nuevo en el periodo' : 'Ya identificado') + '</small>' + '</div>' + '<span class="summary-table-number">' + formatNumber(actor.posts) + ' posts' + '</span>' + '<span class="summary-table-date">' + escapeHtml(formatDateTime(actor.last_activity)) + '</span>' + '</div>';
    }).join('') + '</div>';
  }
  function buildNetwork(edges) {
    if (edges.length === 0) {
      return buildZeroState('Sin relaciones', 'No existen menciones directas entre cuentas.');
    }
    var source = edges[0].source_handle;
    var targets = [];
    edges.forEach(function (edge) {
      if (targets.indexOf(edge.mentioned_handle) === -1) {
        targets.push(edge.mentioned_handle);
      }
    });
    targets = targets.slice(0, 4);
    return '<div class="summary-network">' + '<svg viewBox="0 0 100 100" preserveAspectRatio="none">' + '<line x1="50" y1="50" x2="16" y2="22"></line>' + '<line x1="50" y1="50" x2="84" y2="22"></line>' + '<line x1="50" y1="50" x2="18" y2="80"></line>' + '<line x1="50" y1="50" x2="82" y2="80"></line>' + '</svg>' + '<span class="summary-network-node summary-network-source">' + escapeHtml('@' + String(source || '').replace(/^@/, '')) + '</span>' + (targets[0] ? '<span class="summary-network-node summary-network-a">' + escapeHtml(targets[0]) + '</span>' : '') + (targets[1] ? '<span class="summary-network-node summary-network-b">' + escapeHtml(targets[1]) + '</span>' : '') + (targets[2] ? '<span class="summary-network-node summary-network-c">' + escapeHtml(targets[2]) + '</span>' : '') + (targets[3] ? '<span class="summary-network-node summary-network-d">' + escapeHtml(targets[3]) + '</span>' : '') + '</div>';
  }

  /* =========================================================
     PANORAMA
     ========================================================= */

  function syncOverview(coreRow, historyRow) {
    var postTypes = getArrayField(coreRow, 'post_types');
    var hashtags = getArrayField(coreRow, 'hashtags');
    var recent = getArrayField(coreRow, 'recent_posts');
    var historyTimeline = getArrayField(historyRow, 'timeline');
    setMetricCard('overview', 0, {
      icon: '▣',
      label: 'Publicaciones',
      value: formatNumber(coreRow ? coreRow.posts_period : 0),
      foot: 'Posts ingeridos en el periodo'
    });
    setMetricCard('overview', 1, {
      icon: '↗',
      label: 'Interacciones',
      value: formatNumber(coreRow ? coreRow.interactions_period : 0),
      foot: 'Likes, comentarios y compartidos'
    });
    setMetricCard('overview', 2, {
      icon: '◯',
      label: 'Comentarios',
      value: formatNumber(coreRow ? coreRow.comments_period : 0),
      foot: 'Comentarios registrados'
    });
    setMetricCard('overview', 3, {
      icon: '▶',
      label: 'Visualizaciones',
      value: formatNumber(coreRow ? coreRow.views_period : 0),
      foot: 'Visualizaciones registradas'
    });
    setPanelHeading('overview', 0, 'Crecimiento observado de interacciones', 'Incrementos registrados entre snapshots históricos de métricas.');
    setPanelBody('overview', 0, 'summary-live-chart-wrap', buildTimelineChart(historyTimeline, 'interactions_gained', '#31B98A', historyRow ? formatNumber(historyRow.interactions_gained) + ' interacciones ganadas observadas · ' + formatNumber(historyRow.posts_with_observed_change) + ' posts con evolución' : ''));
    setPanelHeading('overview', 1, 'Formatos publicados', 'Distribución real por tipo de contenido.');
    setPanelBody('overview', 1, 'summary-live-donut-wrap', buildDonut(postTypes.map(function (item) {
      return {
        label: postTypeLabel(item.post_type),
        value: Number(item.posts || 0)
      };
    }), formatNumber(coreRow ? coreRow.posts_period : 0), 'Posts'));
    setPanelHeading('overview', 2, 'Hashtags principales', 'Etiquetas más utilizadas en las publicaciones.');
    setPanelBody('overview', 2, 'summary-hashtags-wrap', buildHashtags(hashtags, 7));
    setPanelHeading('overview', 3, 'Actividad reciente', 'Últimas publicaciones incorporadas al histórico.');
    setPanelBody('overview', 3, 'summary-post-list-wrap', buildPosts(recent, 5));
  }

  /* =========================================================
     CONVERSACIÓN
     ========================================================= */

  function syncConversation(coreRow) {
    var timeline = getArrayField(coreRow, 'timeline');
    var hashtags = getArrayField(coreRow, 'hashtags');
    var recent = getArrayField(coreRow, 'recent_posts');
    var topPosts = getArrayField(coreRow, 'top_posts');
    setMetricCard('conversation', 0, {
      icon: '▣',
      label: 'Posts',
      value: formatNumber(coreRow ? coreRow.posts_period : 0),
      foot: 'Publicaciones durante el periodo'
    });
    setMetricCard('conversation', 1, {
      icon: '♥',
      label: 'Likes',
      value: formatNumber(coreRow ? coreRow.likes_period : 0),
      foot: 'Reacciones registradas'
    });
    setMetricCard('conversation', 2, {
      icon: '◎',
      label: 'Días activos',
      value: formatNumber(coreRow ? coreRow.active_days : 0),
      foot: 'Días con publicaciones'
    });
    setMetricCard('conversation', 3, {
      icon: '⌁',
      label: 'Promedio',
      value: formatDecimal(coreRow ? coreRow.avg_interactions_per_post : 0),
      foot: 'Interacciones por publicación'
    });
    setPanelHeading('conversation', 0, 'Ritmo de publicación', 'Número de publicaciones durante el periodo.');
    setPanelBody('conversation', 0, 'summary-live-chart-wrap', buildTimelineChart(timeline, 'posts', '#31B98A', ''));
    setPanelHeading('conversation', 1, 'Temas recurrentes', 'Hashtags utilizados directamente en los posts.');
    setPanelBody('conversation', 1, 'summary-hashtags-wrap', buildHashtags(hashtags, 7));
    setPanelHeading('conversation', 2, 'Publicaciones recientes', 'Último contenido incorporado por la ingesta.');
    setPanelBody('conversation', 2, 'summary-post-list-wrap', buildPosts(recent, 6));
    setPanelHeading('conversation', 3, 'Mayor interacción', 'Publicaciones con mayor respuesta de la audiencia.');
    setPanelBody('conversation', 3, 'summary-post-list-wrap', buildPosts(topPosts, 5));
  }

  /* =========================================================
     FUENTES
     ========================================================= */

  function syncSources(coreRow) {
    var platforms = getArrayField(coreRow, 'platforms');
    var accounts = getArrayField(coreRow, 'accounts');
    setMetricCard('sources', 0, {
      icon: '◇',
      label: 'Plataformas',
      value: formatNumber(coreRow ? coreRow.active_platforms : 0),
      foot: 'Plataformas con publicaciones'
    });
    setMetricCard('sources', 1, {
      icon: '@',
      label: 'Cuentas activas',
      value: formatNumber(coreRow ? coreRow.active_accounts : 0),
      foot: 'Perfiles con actividad'
    });
    setMetricCard('sources', 2, {
      icon: '▣',
      label: 'Posts ingeridos',
      value: formatNumber(coreRow ? coreRow.posts_period : 0),
      foot: 'Contenido disponible en el periodo'
    });
    setMetricCard('sources', 3, {
      icon: '✓',
      label: 'Última actividad',
      value: formatDateTime(coreRow ? coreRow.last_activity : null),
      foot: 'Publicación más reciente'
    });
    setPanelHeading('sources', 0, 'Participación por plataforma', 'Volumen de publicaciones ingeridas.');
    setPanelBody('sources', 0, 'summary-platform-bars', buildPlatformBars(platforms));
    setPanelHeading('sources', 1, 'Distribución por plataforma', 'Participación según volumen de posts.');
    setPanelBody('sources', 1, 'summary-live-donut-wrap', buildDonut(platforms.map(function (item) {
      return {
        label: platformLabel(item.platform),
        value: Number(item.posts || 0)
      };
    }), formatNumber(coreRow ? coreRow.posts_period : 0), 'Posts'));
    setPanelHeading('sources', 2, 'Rendimiento por plataforma', 'Volumen, interacción y actividad reciente.');
    setPanelBody('sources', 2, 'summary-platform-table-wrap', buildPlatformTable(platforms));
    setPanelHeading('sources', 3, 'Cuentas con actividad', 'Perfiles sociales incorporados mediante la ingesta.');
    setPanelBody('sources', 3, 'summary-account-table-wrap', buildAccountTable(accounts));
  }

  /* =========================================================
     ACTORES
     ========================================================= */

  function syncActors(coreRow) {
    var actors = normalizeActors(getArrayField(coreRow, 'mentioned_accounts'));
    var edges = normalizeEdges(getArrayField(coreRow, 'mention_edges'));
    var recurrent = actors.filter(function (actor) {
      return actor.posts >= 2;
    }).length;
    var newActors = actors.filter(function (actor) {
      return actor.is_new === true;
    }).length;
    var directMentions = actors.reduce(function (total, actor) {
      return total + actor.posts;
    }, 0);
    setMetricCard('actors', 0, {
      icon: '◎',
      label: 'Actores detectados',
      value: formatNumber(actors.length),
      foot: 'Cuentas mencionadas en posts'
    });
    setMetricCard('actors', 1, {
      icon: '★',
      label: 'Actores recurrentes',
      value: formatNumber(recurrent),
      foot: 'Mencionados en 2 o más posts'
    });
    setMetricCard('actors', 2, {
      icon: '+',
      label: 'Nuevos actores',
      value: formatNumber(newActors),
      foot: 'Primera aparición en el periodo'
    });
    setMetricCard('actors', 3, {
      icon: '@',
      label: 'Menciones directas',
      value: formatNumber(directMentions),
      foot: 'Referencias @ detectadas'
    });
    setPanelHeading('actors', 0, 'Actores principales', 'Cuentas más mencionadas dentro de las publicaciones.');
    setPanelBody('actors', 0, 'summary-actor-grid', buildActorCards(actors));
    setPanelHeading('actors', 1, 'Red de relaciones', 'Vínculos entre las cuentas publicadoras y las cuentas mencionadas.');
    setPanelBody('actors', 1, 'summary-network-wrap', buildNetwork(edges));
    setPanelHeading('actors', 2, 'Ranking de menciones', 'Actores ordenados por número de publicaciones en las que aparecen.');
    setPanelBody('actors', 2, 'summary-ranking-wrap', buildActorRanking(actors));
    setPanelHeading('actors', 3, 'Actividad reciente', 'Última aparición registrada de cada actor.');
    setPanelBody('actors', 3, 'summary-actor-activity-wrap', buildActorActivity(actors));
  }

  /* =========================================================
     CABECERA
     ========================================================= */

  function syncHeader(coreRow) {
    var small = document.querySelector('.query-context small');
    var name = document.getElementById('summaryQueryName');
    var dot = document.querySelector('.query-context-dot');
    if (small) {
      small.textContent = 'Periodo analizado';
    }
    if (name) {
      if (coreRow) {
        name.textContent = formatNumber(coreRow.posts_period) + ' posts · ' + getPeriodLabel(currentPeriod);
      } else {
        name.textContent = 'Actualizando…';
      }
    }
    if (dot) {
      dot.style.opacity = coreRow ? '1' : '0.3';
    }
  }

  /* =========================================================
     PERIODO
     ========================================================= */

  function syncPeriod() {
    var select = document.getElementById('summaryPeriod');
    if (select && select.value !== currentPeriod) {
      select.value = currentPeriod;
    }
  }
  async function changePeriod(period) {
    var value = normalizePeriod(period);
    if (value === currentPeriod) {
      return;
    }
    currentPeriod = value;
    syncPeriod();

    /*
     * Los resultados anteriores dejan
     * temporalmente de ser válidos.
     */
    syncWidget();
    try {
      await appsmith.updateModel({
        period: value
      });
      requestRefresh();
    } catch (error) {
      console.error('No fue posible cambiar el periodo:', error);
    }
  }
  function bindPeriod() {
    var select = document.getElementById('summaryPeriod');
    if (!select) {
      return;
    }
    select.addEventListener('change', function () {
      changePeriod(select.value);
    });
  }

  /* =========================================================
     NAVEGACIÓN
     ========================================================= */

  function setActiveViewVisual(view) {
    document.querySelectorAll('.summary-nav-item').forEach(function (item) {
      var active = item.getAttribute('data-view') === view;
      item.classList.toggle('active', active);
      item.setAttribute('aria-current', active ? 'page' : 'false');
    });
    document.querySelectorAll('[data-view-panel]').forEach(function (panel) {
      panel.classList.toggle('active', panel.getAttribute('data-view-panel') === view);
    });
    var meta = viewMeta[view] || viewMeta.overview;
    var title = document.getElementById('summaryTitle');
    var subtitle = document.getElementById('summarySubtitle');
    if (title) {
      title.textContent = meta.title;
    }
    if (subtitle) {
      subtitle.textContent = meta.subtitle;
    }
  }
  function changeView(view) {
    currentView = normalizeView(view);
    setActiveViewVisual(currentView);
  }
  function bindNavigation() {
    document.querySelectorAll('.summary-nav-item').forEach(function (item) {
      item.addEventListener('click', function () {
        changeView(item.getAttribute('data-view'));
      });
    });
  }

  /* =========================================================
     RENDER
     ========================================================= */

  function syncWidget(modelOverride) {
    var coreRow = getCoreRow(modelOverride);
    var historyRow = getHistoryRow(modelOverride);
    setActiveViewVisual(currentView);
    syncPeriod();
    syncHeader(coreRow);
    syncOverview(coreRow, historyRow);
    syncConversation(coreRow);
    syncSources(coreRow);
    syncActors(coreRow);
    setActiveViewVisual(currentView);
    syncPeriod();
  }

  /* =========================================================
     REFRESH
     ========================================================= */

  function getRefreshKey() {
    return currentPeriod;
  }
  function requestRefresh() {
    var key = getRefreshKey();
    if (key === lastRefreshKey) {
      return;
    }
    lastRefreshKey = key;
    appsmith.triggerEvent('onRefreshSummary');
  }

  /* =========================================================
     INICIO
     ========================================================= */

  injectStyles();
  bindNavigation();
  bindPeriod();
  syncWidget();
  requestRefresh();
  if (typeof appsmith.onModelChange === 'function') {
    appsmith.onModelChange(function (newModel) {
      syncWidget(newModel);
      requestRefresh();
    });
  }
});

