@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap");

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
}

body {
  font-family: "DM Sans", sans-serif;
  background: transparent;
  color: #2F323B;
}

button,
select {
  font-family: inherit;
}

.summary-shell {
  --ink: #2F323B;
  --blue: #2972A9;
  --cyan: #2E9BCB;
  --light-blue: #A7CDDE;
  --paper: #FFFFFF;
  --surface: #F7FAFC;
  --surface-blue: rgba(167, 205, 222, 0.13);
  --line: rgba(167, 205, 222, 0.55);
  --line-soft: rgba(167, 205, 222, 0.28);
  --muted: #727780;
  --green: #1EAF73;
  --red: #E6505C;
  --orange: #E79A2E;

  width: 100%;
  min-height: 100%;

  display: grid;
  grid-template-columns: 190px minmax(0, 1fr);

  gap: 14px;

  padding: 8px;

  background:
    linear-gradient(
      180deg,
      #F8FBFD 0%,
      #FFFFFF 100%
    );
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.summary-sidebar {
  min-height: 680px;

  padding: 16px 10px;

  border: 1px solid var(--line);

  border-radius: 18px;

  background:
    linear-gradient(
      180deg,
      rgba(247, 250, 252, 0.98),
      rgba(255, 255, 255, 0.98)
    );

  box-shadow:
    0 10px 24px
    rgba(47, 50, 59, 0.06);
}

.sidebar-heading {
  padding: 5px 10px 16px;

  display: flex;
  flex-direction: column;
}

.sidebar-heading span {
  color: var(--cyan);

  font-size: 8px;
  font-weight: 700;

  letter-spacing: 0.15em;
}

.sidebar-heading strong {
  margin-top: 4px;

  color: var(--ink);

  font-family:
    "Playfair Display",
    serif;

  font-size: 18px;
}

.summary-nav {
  display: flex;
  flex-direction: column;

  gap: 5px;
}

.summary-nav-item {
  width: 100%;
  min-height: 54px;

  display: flex;
  align-items: center;

  gap: 11px;

  padding: 8px 10px;

  border: 0;
  border-radius: 12px;

  background: transparent;

  color: var(--muted);

  cursor: pointer;

  text-align: left;

  transition:
    color 0.2s,
    background 0.2s,
    transform 0.2s;
}

.summary-nav-item:hover {
  color: var(--blue);

  background:
    rgba(167, 205, 222, 0.14);
}

.summary-nav-item.active {
  color: var(--blue);

  background:
    linear-gradient(
      90deg,
      rgba(46, 155, 203, 0.15),
      rgba(167, 205, 222, 0.10)
    );
}

.summary-nav-item.active::before {
  content: "";

  width: 3px;
  height: 30px;

  margin-left: -10px;

  border-radius: 0 4px 4px 0;

  background:
    linear-gradient(
      180deg,
      var(--blue),
      var(--cyan)
    );
}

.summary-nav-icon {
  width: 28px;
  height: 28px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 9px;

  background:
    rgba(41, 114, 169, 0.07);

  font-size: 14px;
  font-weight: 700;
}

.summary-nav-item.active
.summary-nav-icon {
  background:
    rgba(46, 155, 203, 0.14);
}

.summary-nav-copy {
  min-width: 0;

  display: flex;
  flex-direction: column;
}

.summary-nav-copy strong {
  color: inherit;

  font-size: 11px;
  font-weight: 700;
}

.summary-nav-copy small {
  margin-top: 2px;

  color: #969BA2;

  font-size: 8px;
}


/* =========================================================
   MAIN
   ========================================================= */

.summary-main {
  min-width: 0;

  padding: 4px 2px 14px;
}

.summary-header {
  min-height: 78px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 24px;

  margin-bottom: 14px;
}

.summary-heading {
  min-width: 0;
}

.summary-kicker {
  color: var(--cyan);

  font-size: 8px;
  font-weight: 700;

  letter-spacing: 0.15em;
}

.summary-heading h1 {
