  font-size: 10px;
}

.summary-header-controls {
  display: flex;
  align-items: center;

  gap: 8px;
}

.query-context {
  min-width: 170px;
  height: 45px;

  display: flex;
  align-items: center;

  gap: 8px;

  padding: 0 12px;

  border: 1px solid var(--line);

  border-radius: 12px;

  background: #FFFFFF;
}

.query-context-dot {
  width: 8px;
  height: 8px;

  border-radius: 50%;

  background: #47D7A0;

  flex-shrink: 0;
}

.query-context div {
  min-width: 0;

  display: flex;
  flex-direction: column;
}

.query-context small {
  color: #969BA2;

  font-size: 7px;

