}

.metric-value-small {
  font-size: 17px;
}

.metric-foot {
  display: block;

  margin-top: 7px;

  color: #989DA4;

  font-size: 8px;
}


/* =========================================================
   PANELS
   ========================================================= */

.content-grid {
  display: grid;

  gap: 12px;

  margin-top: 12px;
}

.primary-grid {
  grid-template-columns:
    minmax(0, 1.65fr)
    minmax(280px, 0.95fr);
}

.secondary-grid {
  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );
}

.panel-card {
  min-width: 0;
  min-height: 235px;

  padding: 15px;

  border: 1px solid var(--line);

  border-radius: 16px;

  background:
    rgba(255, 255, 255, 0.96);

  box-shadow:
    0 8px 22px
    rgba(47, 50, 59, 0.045);
