  opacity: 0.6;
}


/* actores */

.actor-placeholder-grid {
  display: grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0, 1fr)
    );

  gap: 9px;

  margin-top: 18px;
}

.actor-placeholder {
  min-height: 130px;

  display: flex;
  flex-direction: column;

  align-items: center;
  justify-content: center;

  padding: 10px;

  border:
    1px solid
    var(--line-soft);

  border-radius: 12px;

  background: #FFFFFF;
}

.actor-placeholder > span {
  width: 42px;
  height: 42px;

  border-radius: 50%;

  background:
    linear-gradient(
      145deg,
      #E7F3F9,
      #D5E7EF
    );
}

.actor-placeholder strong {
  margin-top: 8px;

  color: var(--ink);

  font-size: 9px;
}

.actor-placeholder small {
  margin-top: 2px;

  color: #969BA2;

  font-size: 7px;
}

.network-placeholder {
  min-height: 170px;

  margin-top: 8px;

  position: relative;

  border-radius: 12px;

  background:
    radial-gradient(
      circle at center,
      rgba(46, 155, 203, 0.09),
      transparent 47%
    );
}

.network-node {
  position: absolute;

  min-width: 54px;

  padding: 6px 9px;

  border:
    1px solid
    var(--line);

  border-radius: 999px;

  background: #FFFFFF;

  color: var(--blue);

  font-size: 7px;

  text-align: center;
}

.node-main {
  left: 50%;
  top: 50%;

  transform:
    translate(
      -50%,
      -50%
    );

  color: #FFFFFF;

  background:
    linear-gradient(
      135deg,
      var(--blue),
      var(--cyan)
    );
}

.node-a {
  left: 9%;
  top: 21%;
}

.node-b {
  right: 10%;
  top: 18%;
}

.node-c {
  right: 17%;
  bottom: 15%;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {

  .summary-shell {
    grid-template-columns:
      76px
      minmax(0, 1fr);
  }

  .sidebar-heading {
    display: none;
  }

  .summary-nav-copy {
    display: none;
  }

  .summary-nav-item {
    justify-content: center;
  }

  .summary-nav-item.active::before {
    position: absolute;
    left: 0;

    margin-left: 0;
  }

  .summary-nav-item {
    position: relative;
  }

  .metric-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

  .actor-placeholder-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

}


@media (max-width: 780px) {

  .summary-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .summary-header-controls {
    width: 100%;

    flex-wrap: wrap;
  }

  .query-context {
    flex: 1;
  }

  .metric-grid,
  .primary-grid,
  .secondary-grid {
    grid-template-columns: 1fr;
  }

}

