        if (
          !map[
            handle
          ]
        ) {

          map[
            handle
          ] = {
            handle:
              handle,

            posts:
              0,

            source_accounts:
              0,

            first_seen_period:
              row.first_seen_period ||
              null,

            first_seen_history:
              row.first_seen_history ||
              null,

            last_activity:
              row.last_activity ||
              null,

            is_new:
              row.is_new ===
              true
          };

        }


        map[
          handle
        ].posts +=
          Number(
            row.posts ||
            0
          );


        map[
          handle
        ].source_accounts =
          Math.max(
            map[
              handle
            ].source_accounts,

            Number(
              row.source_accounts ||
              0
            )
          );


        if (
          row.last_activity &&
          (
            !map[
              handle
            ].last_activity ||
            new Date(
              row.last_activity
            ) >
            new Date(
              map[
                handle
              ].last_activity
            )
          )
        ) {

          map[
            handle
          ].last_activity =
            row.last_activity;

        }


        if (
          row.first_seen_history &&
          (
            !map[
              handle
            ].first_seen_history ||
            new Date(
              row.first_seen_history
            ) <
            new Date(
              map[
                handle
              ].first_seen_history
            )
          )
        ) {

          map[
            handle
          ].first_seen_history =
            row.first_seen_history;

        }


        map[
          handle
        ].is_new =
          map[
            handle
          ].is_new &&
          row.is_new ===
            true;

      }
    );


    return Object.keys(
      map
    )
      .map(
        function (
          key
        ) {

          return map[
            key
          ];

        }
      )
      .sort(
        function (
          a,
          b
        ) {

          return (
            b.posts -
            a.posts
          );

        }
      );
  }


  function normalizeEdges(
    rows
  ) {
    var map =
      {};


    (
      Array.isArray(
        rows
      )
        ? rows
        : []
    ).forEach(
      function (
        row
      ) {

        var source =
          String(
            row.source_handle ||
            ''
          ).trim();


        var target =
          normalizeHandle(
            row.mentioned_handle
          );


        if (
          !source ||
          !target
        ) {
          return;
        }


        var key =
          source +
          '|' +
          String(
            row.platform ||
            ''
          ) +
          '|' +
          target;


        if (
          !map[
            key
          ]
        ) {

          map[
            key
          ] = {
            source_handle:
              source,

            platform:
              row.platform,

            mentioned_handle:
              target,

            posts:
              0
          };

        }


        map[
          key
        ].posts +=
          Number(
            row.posts ||
            0
          );

      }
    );


    return Object.keys(
      map
    )
      .map(
        function (
          key
        ) {

          return map[
            key
          ];

        }
      )
      .sort(
        function (
          a,
          b
        ) {

          return (
            b.posts -
            a.posts
          );

        }
      );
  }


