  function getView(
    viewId
  ) {
    return document.getElementById(
      'view-' +
      viewId
    );
  }


  function getMetricCards(
    viewId
  ) {
    var view =
      getView(
        viewId
      );


    if (!view) {
      return [];
    }


    return Array.from(
      view.querySelectorAll(
        '.metric-grid .metric-card'
      )
    );
  }


  function setMetricCard(
    viewId,
    index,
    config
  ) {
    var cards =
      getMetricCards(
        viewId
      );


    var card =
      cards[
        index
      ];


    if (!card) {
      return;
    }


    var icon =
      card.querySelector(
        '.metric-icon'
      );


    var label =
      card.querySelector(
        '.metric-top > span:last-child'
      );


    var value =
      card.querySelector(
        '.metric-value'
      );


    var foot =
      card.querySelector(
        '.metric-foot'
      );


    if (
      icon &&
      config.icon !==
        undefined
    ) {

      icon.textContent =
        config.icon;


      icon.classList.remove(
        'warning'
      );

    }


    if (
      label &&
      config.label !==
        undefined
    ) {
      label.textContent =
        config.label;
    }


    if (
      value &&
      config.value !==
        undefined
    ) {
      value.textContent =
        config.value;
    }


    if (
      foot &&
      config.foot !==
        undefined
    ) {
      foot.textContent =
        config.foot;
    }
  }


