  /* =========================================================
     GRÁFICO
     ========================================================= */

  function buildTimelineChart(
    timeline,
    field,
    color,
    note
  ) {
    if (
      !Array.isArray(
        timeline
      ) ||
      timeline.length ===
        0
    ) {

      return buildZeroState(
        'Sin actividad',
        'No existen datos para el periodo.'
      );

    }


    var rows =
      timeline.map(
        function (
          row
        ) {

          return {
            bucket:
              row.bucket,

            value:
              Number(
                row[
                  field
                ] ||
                0
              )
          };

        }
      );


    var maxValue =
      Math.max(
        1,
        Math.max.apply(
          null,
          rows.map(
            function (
              row
            ) {

              return row.value;

            }
          )
        )
      );


    var width =
      1000;

    var height =
      205;

    var padX =
      22;

    var padTop =
      16;

    var padBottom =
      26;


    var usableWidth =
      width -
      (
        padX *
        2
      );


    var usableHeight =
      height -
      padTop -
      padBottom;


    var points =
      rows.map(
        function (
          row,
          index
        ) {

          var denominator =
            Math.max(
              rows.length -
              1,
              1
            );


          return {
            x:
              padX +
              (
                index /
                denominator
              ) *
              usableWidth,

            y:
              padTop +
              usableHeight -
              (
                row.value /
                maxValue
              ) *
              usableHeight,

            value:
              row.value,

            bucket:
              row.bucket
          };

        }
      );


    var polyline =
      points
        .map(
          function (
            point
          ) {

            return (
              point.x.toFixed(
                2
              ) +
              ',' +
              point.y.toFixed(
                2
              )
            );

          }
        )
        .join(
          ' '
        );


    var grid =
      [
        0,
        0.25,
        0.5,
        0.75,
        1
      ]
        .map(
          function (
            ratio
          ) {

            var y =
              padTop +
              (
                usableHeight *
                ratio
              );


            return (
              '<line' +
                ' class="summary-chart-grid"' +
                ' x1="' +
                  padX +
                '"' +
                ' y1="' +
                  y +
                '"' +
                ' x2="' +
                  (
                    width -
                    padX
                  ) +
                '"' +
                ' y2="' +
                  y +
                '"' +
              '></line>'
            );

          }
        )
        .join(
          ''
        );


    var dots =
      points
        .filter(
          function (
            point
          ) {

            return (
              point.value >
              0
            );

          }
        )
        .map(
          function (
            point,
            index
          ) {

            return (
              '<circle' +
                ' class="summary-chart-point"' +
                ' cx="' +
                  point.x +
                '"' +
                ' cy="' +
                  point.y +
                '"' +
                ' r="4.5"' +
                ' fill="' +
                  getColor(
                    index +
