  /* =========================================================
     DONUT
     ========================================================= */

  function buildDonut(
    items,
    centerValue,
    centerLabel
  ) {
    var rows =
      (
        Array.isArray(
          items
        )
          ? items
          : []
      )
        .filter(
          function (
            item
          ) {

            return (
              Number(
                item.value ||
                0
              ) >
              0
            );

          }
        );


    var total =
      rows.reduce(
        function (
          sum,
          item
        ) {

          return (
            sum +
            Number(
              item.value ||
              0
            )
          );

        },
        0
      );


    if (
      total <=
      0
    ) {

      return buildZeroState(
        '0 registros',
        'No hay información para construir la distribución.'
      );

    }


    var cursor =
      0;


    var segments =
      rows
        .map(
          function (
            item,
            index
          ) {

            var start =
              cursor;


            var end =
              cursor +
              (
                Number(
                  item.value
                ) /
                total
              ) *
              100;


            cursor =
              end;


            return (
              getColor(
                index
              ) +
              ' ' +
              start.toFixed(
                2
              ) +
              '% ' +
              end.toFixed(
                2
              ) +
              '%'
            );

          }
        )
        .join(
          ','
        );


    var legend =
      rows
        .map(
          function (
            item,
            index
          ) {

            var percentage =
              (
                Number(
                  item.value
                ) /
                total
              ) *
              100;


            return (
              '<div class="summary-live-legend-row">' +

                '<span' +
                  ' class="summary-live-legend-dot"' +
                  ' style="background:' +
                    getColor(
                      index
                    ) +
                  '"' +
                '></span>' +

                '<span class="summary-live-legend-name">' +
                  escapeHtml(
                    item.label
                  ) +
                '</span>' +

                '<strong>' +
                  formatNumber(
                    item.value
                  ) +
                  ' · ' +
                  formatDecimal(
                    percentage
                  ) +
                  '%' +
                '</strong>' +

              '</div>'
            );

          }
        )
        .join(
          ''
        );


    return (
      '<div class="summary-live-donut-layout">' +

        '<div' +
          ' class="summary-live-donut"' +
          ' style="background:conic-gradient(' +
            segments +
          ')"' +
        '>' +

          '<div class="summary-live-donut-center">' +

            '<strong>' +
              escapeHtml(
                centerValue
              ) +
            '</strong>' +

            '<small>' +
              escapeHtml(
                centerLabel
              ) +
            '</small>' +

          '</div>' +

        '</div>' +

        '<div class="summary-live-legend">' +
          legend +
        '</div>' +

      '</div>'
    );
  }


