  function buildNetwork(
    edges
  ) {
    if (
      edges.length ===
      0
    ) {

      return buildZeroState(
        'Sin relaciones',
        'No existen menciones directas entre cuentas.'
      );

    }


    var source =
      edges[
        0
      ].source_handle;


    var targets =
      [];


    edges.forEach(
      function (
        edge
      ) {

        if (
          targets.indexOf(
            edge.mentioned_handle
          ) === -1
        ) {

          targets.push(
            edge.mentioned_handle
          );

        }

      }
    );


    targets =
      targets.slice(
        0,
        4
      );


    return (
      '<div class="summary-network">' +

        '<svg viewBox="0 0 100 100" preserveAspectRatio="none">' +

          '<line x1="50" y1="50" x2="16" y2="22"></line>' +
          '<line x1="50" y1="50" x2="84" y2="22"></line>' +
          '<line x1="50" y1="50" x2="18" y2="80"></line>' +
          '<line x1="50" y1="50" x2="82" y2="80"></line>' +

        '</svg>' +

        '<span class="summary-network-node summary-network-source">' +
          escapeHtml(
            '@' +
            String(
              source ||
              ''
            ).replace(
              /^@/,
              ''
            )
          ) +
        '</span>' +

        (
          targets[
            0
          ]
            ? (
                '<span class="summary-network-node summary-network-a">' +
                  escapeHtml(
                    targets[
                      0
                    ]
                  ) +
                '</span>'
              )
            : ''
        ) +

        (
          targets[
            1
          ]
            ? (
                '<span class="summary-network-node summary-network-b">' +
                  escapeHtml(
                    targets[
