     ========================================================= */

  function syncActors(
    coreRow
  ) {
    var actors =
      normalizeActors(
        getArrayField(
          coreRow,
          'mentioned_accounts'
        )
      );


    var edges =
      normalizeEdges(
        getArrayField(
          coreRow,
          'mention_edges'
        )
      );


    var recurrent =
      actors.filter(
        function (
          actor
        ) {

          return (
            actor.posts >=
            2
          );

        }
      ).length;


    var newActors =
      actors.filter(
        function (
          actor
        ) {

          return (
            actor.is_new ===
            true
          );

        }
      ).length;


    var directMentions =
      actors.reduce(
        function (
          total,
          actor
        ) {

          return (
            total +
            actor.posts
          );

        },
        0
      );


    setMetricCard(
      'actors',
      0,
      {
        icon:
          '◎',

        label:
          'Actores detectados',

        value:
          formatNumber(
            actors.length
          ),

