  function syncHeader(
    coreRow
  ) {
    var small =
      document.querySelector(
        '.query-context small'
      );


    var name =
      document.getElementById(
        'summaryQueryName'
      );


    var dot =
      document.querySelector(
        '.query-context-dot'
      );


    if (small) {
      small.textContent =
        'Periodo analizado';
    }


    if (name) {

      if (coreRow) {

        name.textContent =
          formatNumber(
            coreRow.posts_period
          ) +
          ' posts · ' +
          getPeriodLabel(
            currentPeriod
          );

      } else {

        name.textContent =
          'Actualizando…';

      }

    }


    if (dot) {

      dot.style.opacity =
        coreRow
          ? '1'
          : '0.3';

    }
  }


  /* =========================================================
     PERIODO
     ========================================================= */

  function syncPeriod() {
    var select =
      document.getElementById(
        'summaryPeriod'
      );


    if (
      select &&
      select.value !==
        currentPeriod
    ) {

      select.value =
        currentPeriod;

    }
  }


  async function changePeriod(
    period
  ) {
    var value =
      normalizePeriod(
        period
      );


    if (
      value ===
      currentPeriod
    ) {
      return;
    }


    currentPeriod =
      value;


    syncPeriod();


    /*
     * Los resultados anteriores dejan
     * temporalmente de ser válidos.
     */
    syncWidget();


    try {

      await appsmith.updateModel({
        period:
          value
      });


      requestRefresh();

    } catch (
      error
    ) {

      console.error(
        'No fue posible cambiar el periodo:',
        error
      );

    }
  }


  function bindPeriod() {
    var select =
      document.getElementById(
        'summaryPeriod'
      );


    if (!select) {
      return;
    }


    select.addEventListener(
      'change',
      function () {

        changePeriod(
          select.value
        );

      }
    );
  }


  /* =========================================================
     NAVEGACIÓN
     ========================================================= */

  function setActiveViewVisual(
    view
  ) {
    document
      .querySelectorAll(
        '.summary-nav-item'
      )
      .forEach(
        function (
          item
        ) {

          var active =
            item.getAttribute(
              'data-view'
            ) ===
            view;


          item.classList.toggle(
            'active',
            active
          );


          item.setAttribute(
            'aria-current',
            active
              ? 'page'
              : 'false'
          );

        }
      );


    document
      .querySelectorAll(
        '[data-view-panel]'
      )
      .forEach(
        function (
          panel
        ) {

          panel.classList.toggle(
            'active',
            panel.getAttribute(
              'data-view-panel'
            ) ===
              view
          );

        }
      );


    var meta =
      viewMeta[
        view
      ] ||
      viewMeta.overview;


    var title =
      document.getElementById(
        'summaryTitle'
      );


    var subtitle =
      document.getElementById(
        'summarySubtitle'
      );


    if (title) {
      title.textContent =
        meta.title;
    }


    if (subtitle) {
      subtitle.textContent =
        meta.subtitle;
    }
  }


  function changeView(
    view
  ) {
    currentView =
      normalizeView(
        view
      );


    setActiveViewVisual(
      currentView
    );
  }


  function bindNavigation() {
    document
      .querySelectorAll(
        '.summary-nav-item'
      )
      .forEach(
        function (
          item
        ) {

          item.addEventListener(
            'click',
            function () {

              changeView(
                item.getAttribute(
                  'data-view'
                )
              );

            }
          );

        }
      );
  }


  /* =========================================================
     RENDER
     ========================================================= */

  function syncWidget(
    modelOverride
  ) {
    var coreRow =
      getCoreRow(
        modelOverride
      );


    var historyRow =
      getHistoryRow(
        modelOverride
      );


    setActiveViewVisual(
      currentView
    );


    syncPeriod();


    syncHeader(
      coreRow
    );


    syncOverview(
      coreRow,
      historyRow
    );


    syncConversation(
      coreRow
    );


    syncSources(
      coreRow
    );


    syncActors(
      coreRow
    );


    setActiveViewVisual(
      currentView
    );


    syncPeriod();
  }


  /* =========================================================
     REFRESH
     ========================================================= */

  function getRefreshKey() {
    return currentPeriod;
  }


  function requestRefresh() {
    var key =
      getRefreshKey();


    if (
      key ===
      lastRefreshKey
    ) {
      return;
    }


    lastRefreshKey =
      key;


    appsmith.triggerEvent(
      'onRefreshSummary'
    );
  }


  /* =========================================================
     INICIO
     ========================================================= */

  injectStyles();

  bindNavigation();

  bindPeriod();

  syncWidget();

  requestRefresh();


  if (
    typeof appsmith.onModelChange ===
      'function'
  ) {

    appsmith.onModelChange(
      function (
        newModel
      ) {

        syncWidget(
          newModel
        );


        requestRefresh();

      }
    );

  }

});
